{
    "$schema": "https://adaptivecards.io/schemas/adaptive-card.json",
    "type": "AdaptiveCard",
    "version": "1.4",
    "body": [
        {
            "type": "Container",
            "style": "accent",
            "bleed": true,
            "items": [
                {
                    "type": "TextBlock",
                    "text": "✅ Access to the '578 EHRM Training App' is APPROVED!",
                    "weight": "Bolder",
                    "size": "Large",
                    "wrap": true
                },
                {
                    "type": "TextBlock",
                    "text": "Review the information below about the advanced access to the '578 EHRM Training App' that you have now been granted:",
                    "isSubtle": true,
                    "wrap": true
                }
            ]
        },
        {
            "type": "Container",
            "spacing": "Small",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Status:",
                                    "weight": "Bolder",
                                    "spacing": "None",
                                    "size": "Large"
                                }
                            ]
                        },
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "APPROVED",
                                    "color": "Good",
                                    "weight": "Bolder",
                                    "spacing": "None",
                                    "size": "Large"
                                }
                            ],
                            "verticalContentAlignment": "Center"
                        },
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "horizontalAlignment": "Center",
                                    "text": "[578 EHRM Training App](https://apps.gov.powerapps.us/play/e/default-e95f1b23-abaf-45ee-821d-b7ab251ab3bf/a/d0958d55-fe85-425c-83f6-03c659bf4079)",
                                    "isSubtle": true,
                                    "spacing": "None",
                                    "wrap": true
                                }
                            ]
                        }
                    ]
                }
            ]
        },
        {
            "type": "Container",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "FactSet",
                                    "facts": [
                                        {
                                            "title": "User's Name:",
                                            "value": "   @{toUpper(body('Get_item')?['DisplayName_Text'])}"
                                        },
                                        {
                                            "title": "User's Email:",
                                            "value": "   @{body('Get_item')?['UserPrincipleName_Text']}"
                                        },
                                        {
                                            "title": "New Access Level:",
                                            "value": "   @{body('Get_item')?['AccessLevel_Text']}"
                                        }
                                    ]
                                }
                            ]
                        },
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "FactSet",
                                    "facts": [
                                        {
                                            "title": "Accessed Approved By:",
                                            "value": "   @{body('Get_item')?['Author']?['DisplayName']}"
                                        },
                                        {
                                            "title": "Access Approved Date:",
                                            "value": "   @{formatDateTime(body('Get_item')?['AccessStart_dateTime'], 'MMMM d, yyyy ''at'' h:mmtt')}"
                                        },
                                        {
                                            "title": "Access Review/Expiration Date:",
                                            "value": "   @{formatDateTime(body('Get_item')?['AccessStop_dateTime'], 'MMMM d, yyyy ''at'' h:mmtt')}"
                                        }
                                    ]
                                }
                            ]
                        }
                    ]
                }
            ],
            "separator": true,
            "spacing": "Small"
        },
        {
            "type": "Container",
            "spacing": "Medium",
            "items": [
                {
                    "type": "TextBlock",
                    "text": "If you have any questions, concerns, or would like more information about the new access level you have been granted, then please contact the manager/admin who approved your new access (@{body('Get_item')?['Author']?['Email']}).",
                    "weight": "Default",
                    "spacing": "Small",
                    "wrap": true,
                    "seperator": true
                },
                {
                    "type": "TextBlock",
                    "text": "*Additional support & instructions are available on the Edward Hines Jr. VA Hospital's EHRM Deployment SharePoint site: [Hines EHRM SharePoint site](https://dvagov.sharepoint.com/sites/HinesEHRM)*",
                    "spacing": "Large",
                    "wrap": true,
                    "seperator": true,
                    "size": "Small",
                    "color": "Accent"
                }
            ]
        }
    ],
    "actions": [
        {
            "type": "Action.OpenUrl",
            "title": "Open the '578 EHRM Training App'",
            "style": "positive",
            "url": "https://apps.gov.powerapps.us/play/e/default-e95f1b23-abaf-45ee-821d-b7ab251ab3bf/a/d0958d55-fe85-425c-83f6-03c659bf4079"
        },
        {
            "type": "Action.Submit",
            "title": "Contact the App Admins",
            "style": "destructive",
            "associatedInputs": "auto",
            "data": {
                "result": "escalated",
                "actionID": "escalated",
                "resultCode": 400,
                "category": "urgent",
                "emailTo": "kyle.coder@va.gov",
                "emailSubject": "[ADMIN ASSISTANCE] My access to the '578 EHRM Training App' was APPROVED",
                "emailBody": "My recent access to the 578 EHRM Training App was Approved, but I am contacting the app admin regarding that issue.\n\nMy concern about this access approval is:\n\n[User: replace this line with your concern............]"
            }
        }
    ]
}

